-- This file is UTF-8 (it contains an emoji default). Make psql read it as UTF-8 whatever the console code page is.
SET client_encoding = 'UTF8';

-- ============================================================================
-- VEDIQRA backend — PostgreSQL schema (originally reconstructed from the GFTD codebase; see FIXES_README.md)
-- Generated by inspecting backend/src/routes/**, backend/src/utils/db.ts and
-- backend/src/middleware/auth.ts. No old data is restored — this creates an
-- EMPTY database with the structure the current backend code requires.
--
-- Safe to run once against a brand new, empty PostgreSQL database:
--   psql "$DATABASE_URL" -f database/schema.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- EXTENSIONS
-- ---------------------------------------------------------------------------
-- gen_random_uuid() (used for every primary key below) lives in pgcrypto on
-- PostgreSQL < 13. On PG >= 13 it is also available from core, but creating
-- pgcrypto is harmless and keeps this script portable.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------------
-- SLUG HELPERS (Phase 2)
-- ---------------------------------------------------------------------------
-- "Magic Mug" -> "magic-mug". Non-latin names fall back to "item" (made unique by unique_slug).
CREATE OR REPLACE FUNCTION slugify(input text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT COALESCE(
    NULLIF(trim(both '-' from regexp_replace(lower(coalesce(input, '')), '[^a-z0-9]+', '-', 'g')), ''),
    'item')
$$;

-- First free slug in <tbl>.slug for a base: base, base-2, base-3 ...
CREATE OR REPLACE FUNCTION unique_slug(tbl text, base text) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  candidate text := base;
  n integer := 1;
  taken boolean;
BEGIN
  LOOP
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE slug = $1)', tbl) INTO taken USING candidate;
    EXIT WHEN NOT taken;
    n := n + 1;
    candidate := base || '-' || n;
  END LOOP;
  RETURN candidate;
END $$;

-- BEFORE INSERT: derive slug from name when the caller did not supply one.
CREATE OR REPLACE FUNCTION assign_slug_from_name() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    NEW.slug := unique_slug(TG_TABLE_NAME, slugify(NEW.name));
  END IF;
  RETURN NEW;
END $$;


-- ============================================================================
-- GENDERS  (backend/src/routes/genders.ts)
-- ============================================================================
CREATE TABLE genders (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name           TEXT NOT NULL UNIQUE,
    display_name   TEXT NOT NULL,
    icon           TEXT,
    display_order  INTEGER NOT NULL DEFAULT 0,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- CATEGORIES  (backend/src/routes/categories.ts, admin.ts)
-- ============================================================================
CREATE TABLE categories (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name           TEXT NOT NULL,
    description    TEXT,
    icon           TEXT DEFAULT 'Gift',
    icon_type      TEXT NOT NULL DEFAULT 'lucide',   -- 'lucide' | 'emoji' | 'image'
    image_url      TEXT,
    color          TEXT DEFAULT 'from-pink-100 to-pink-50',
    hover_effect   TEXT DEFAULT 'scale',
    display_order  INTEGER NOT NULL DEFAULT 0,
    gender         TEXT,                              -- optional gender scoping, set by admin.ts POST /admin/categories
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Phase 2: URL slug (auto-filled from name when omitted), optional parent (two levels), banner image
    slug           TEXT NOT NULL CONSTRAINT categories_slug_key UNIQUE
                        CONSTRAINT categories_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    parent_id      UUID CONSTRAINT categories_parent_fk REFERENCES categories(id) ON DELETE RESTRICT
                        CONSTRAINT categories_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id),
    banner_url     TEXT
);

CREATE INDEX idx_categories_display_order ON categories (display_order);
CREATE INDEX idx_categories_is_active ON categories (is_active);
CREATE INDEX idx_categories_parent ON categories (parent_id);

-- Two levels only: a parent must itself be top-level, and a category that has children cannot become a child.
-- (Remove this trigger if deeper nesting is ever wanted; nothing else depends on it.)
CREATE OR REPLACE FUNCTION categories_check_hierarchy() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.parent_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM categories WHERE id = NEW.parent_id AND parent_id IS NOT NULL) THEN
      RAISE EXCEPTION 'Categories support two levels: the parent must be a top-level category';
    END IF;
    IF TG_OP = 'UPDATE' AND EXISTS (SELECT 1 FROM categories WHERE parent_id = NEW.id) THEN
      RAISE EXCEPTION 'A category that has subcategories cannot become a subcategory';
    END IF;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_categories_hierarchy ON categories;
CREATE TRIGGER trg_categories_hierarchy
  BEFORE INSERT OR UPDATE OF parent_id ON categories
  FOR EACH ROW EXECUTE FUNCTION categories_check_hierarchy();

DROP TRIGGER IF EXISTS trg_categories_slug ON categories;
CREATE TRIGGER trg_categories_slug
  BEFORE INSERT ON categories
  FOR EACH ROW EXECUTE FUNCTION assign_slug_from_name();


-- ============================================================================
-- PRODUCTS  (backend/src/routes/products.ts, admin.ts, social-proof.ts)
-- ============================================================================
CREATE TABLE products (
    id                              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                            TEXT NOT NULL,
    description                     TEXT,
    price                           NUMERIC(12,2) NOT NULL,
    original_price                  NUMERIC(12,2),
    discount_percentage             NUMERIC(5,2),
    image_url                       TEXT,
    additional_images               TEXT[] DEFAULT '{}',
    stock_quantity                  INTEGER NOT NULL DEFAULT 0,
    track_stock                     BOOLEAN NOT NULL DEFAULT FALSE,   -- TRUE: stock_quantity is enforced/decremented; FALSE: made to order
    sku                             TEXT,
    gender                          TEXT DEFAULT 'unisex',
    category                        TEXT,             -- legacy free-text category label (kept alongside product_categories)
    is_customizable                 BOOLEAN NOT NULL DEFAULT FALSE,
    customization_price             NUMERIC(12,2) DEFAULT 0,
    max_customization_characters    INTEGER DEFAULT 50,
    max_customization_images        INTEGER DEFAULT 10,
    max_customization_lines         INTEGER DEFAULT 0,
    is_active                       BOOLEAN NOT NULL DEFAULT TRUE,
    has_colors                      BOOLEAN NOT NULL DEFAULT FALSE,
    has_sizes                       BOOLEAN NOT NULL DEFAULT FALSE,
    social_proof_enabled            BOOLEAN NOT NULL DEFAULT TRUE,
    social_proof_text               TEXT DEFAULT '🔺 {count} people are viewing this right now',
    social_proof_initial_count      INTEGER DEFAULT 5,
    social_proof_end_count          INTEGER DEFAULT 15,
    created_at                      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                      TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Phase 2: unique URL slug (auto-filled from name when omitted)
    slug                            TEXT NOT NULL CONSTRAINT products_slug_key UNIQUE
                                         CONSTRAINT products_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);

DROP TRIGGER IF EXISTS trg_products_slug ON products;
CREATE TRIGGER trg_products_slug
  BEFORE INSERT ON products
  FOR EACH ROW EXECUTE FUNCTION assign_slug_from_name();

CREATE INDEX idx_products_is_active ON products (is_active);
CREATE INDEX idx_products_gender ON products (LOWER(gender));
CREATE INDEX idx_products_created_at ON products (created_at DESC);
CREATE INDEX idx_products_name_trgm ON products (name);

-- ============================================================================
-- PRODUCT <-> CATEGORY  (many-to-many)
-- ============================================================================
CREATE TABLE product_categories (
