    product_id   UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    category_id  UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    UNIQUE (product_id, category_id)   -- required: routes use ON CONFLICT DO NOTHING
);

CREATE INDEX idx_product_categories_product ON product_categories (product_id);
CREATE INDEX idx_product_categories_category ON product_categories (category_id);

-- ============================================================================
-- PRODUCT COLOR VARIANTS  (product-colors.ts, product-colors-public.ts)
-- ============================================================================
CREATE TABLE product_colors (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id         UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    color_name         TEXT NOT NULL,
    color_code         TEXT,
    image_url          TEXT,
    additional_images  TEXT[] DEFAULT '{}',
    stock_quantity     INTEGER NOT NULL DEFAULT 0,
    price_modifier     NUMERIC(12,2) NOT NULL DEFAULT 0,
    is_active          BOOLEAN NOT NULL DEFAULT TRUE,
    display_order      INTEGER NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_product_colors_product ON product_colors (product_id);

-- ============================================================================
-- PRODUCT SIZE VARIANTS  (product-sizes.ts)
-- ============================================================================
CREATE TABLE product_sizes (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id      UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    size_name       TEXT NOT NULL,
    size_code       TEXT,
    stock_quantity  INTEGER NOT NULL DEFAULT 0,
    price_modifier  NUMERIC(12,2) NOT NULL DEFAULT 0,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    display_order   INTEGER NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
