CREATE INDEX idx_product_sizes_product ON product_sizes (product_id);

-- ---------------------------------------------------------------------------
-- 4. Generic product options
--
--   Product --(product_option_groups)--> Option group --> Values (per product)
--
-- Nothing is global: a value exists only under one product's attachment of a group, so "Size: M" on a
-- T-shirt and "Size: M" on a mug are independent rows with their own price and stock.
-- The database has no idea what "Finish" or "Size" mean; the storefront decides how to render a group.
-- ---------------------------------------------------------------------------
CREATE TABLE option_groups (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name        TEXT NOT NULL,
    slug        TEXT NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- One library group per name ("Finish" cannot exist twice, whatever its slug).
CREATE UNIQUE INDEX uq_option_groups_name ON option_groups (lower(name));

DROP TRIGGER IF EXISTS trg_option_groups_slug ON option_groups;
CREATE TRIGGER trg_option_groups_slug
  BEFORE INSERT ON option_groups
  FOR EACH ROW EXECUTE FUNCTION assign_slug_from_name();

CREATE TABLE product_option_groups (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id       UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    option_group_id  UUID NOT NULL REFERENCES option_groups(id) ON DELETE RESTRICT,
    is_required      BOOLEAN NOT NULL DEFAULT FALSE,
    display_order    INTEGER NOT NULL DEFAULT 0,
    is_active        BOOLEAN NOT NULL DEFAULT TRUE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (product_id, option_group_id)
);
CREATE INDEX idx_pog_product ON product_option_groups (product_id);
CREATE INDEX idx_pog_group ON product_option_groups (option_group_id);

-- Unique-within-group key for a value ("Holographic" -> "holographic"; a repeat becomes "holographic-2").
CREATE OR REPLACE FUNCTION assign_option_value_key() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  base text;
  candidate text;
  n integer := 1;
BEGIN
  IF NEW.value_key IS NULL OR NEW.value_key = '' THEN
    base := slugify(NEW.name);
    candidate := base;
    WHILE EXISTS (SELECT 1 FROM product_option_values
                   WHERE product_option_group_id = NEW.product_option_group_id AND value_key = candidate) LOOP
      n := n + 1;
      candidate := base || '-' || n;
    END LOOP;
    NEW.value_key := candidate;
  END IF;
  RETURN NEW;
END $$;

CREATE TABLE product_option_values (
    id                       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_option_group_id  UUID NOT NULL REFERENCES product_option_groups(id) ON DELETE CASCADE,
    name                     TEXT NOT NULL,
    value_key                TEXT NOT NULL CHECK (value_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    price_modifier           NUMERIC(12,2) NOT NULL DEFAULT 0,   -- added to the product price (may be negative)
    stock_quantity           INTEGER CHECK (stock_quantity IS NULL OR stock_quantity >= 0), -- NULL = not tracked
    display_order            INTEGER NOT NULL DEFAULT 0,
    is_active                BOOLEAN NOT NULL DEFAULT TRUE,
    image_url                TEXT,
    metadata                 JSONB NOT NULL DEFAULT '{}'::jsonb, -- storefront hints, e.g. {"color_code":"#f00","size_code":"XL"}
    created_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (product_option_group_id, value_key)
);
CREATE INDEX idx_pov_group ON product_option_values (product_option_group_id);
-- Lets cart items created before this migration (they carry old colour/size ids) be mapped to option values.
CREATE INDEX idx_pov_legacy_color ON product_option_values ((metadata->>'legacy_color_id')) WHERE metadata ? 'legacy_color_id';
CREATE INDEX idx_pov_legacy_size  ON product_option_values ((metadata->>'legacy_size_id'))  WHERE metadata ? 'legacy_size_id';

DROP TRIGGER IF EXISTS trg_pov_value_key ON product_option_values;
CREATE TRIGGER trg_pov_value_key
  BEFORE INSERT ON product_option_values
  FOR EACH ROW EXECUTE FUNCTION assign_option_value_key();

-- Library groups that the legacy colour/size adapters (and the storefront) expect to exist.
INSERT INTO option_groups (name, slug) VALUES ('Colour', 'colour'), ('Size', 'size');


-- ============================================================================
-- COMBOS  (combos.ts, admin.ts)
-- ============================================================================
CREATE TABLE combos (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                  TEXT NOT NULL,
    description           TEXT,
    discount_percentage   NUMERIC(5,2),
    discount_price        NUMERIC(12,2),
    image_url             TEXT,
    additional_images     TEXT[] DEFAULT '{}',
    is_active             BOOLEAN NOT NULL DEFAULT TRUE,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_combos_is_active ON combos (is_active);
CREATE INDEX idx_combos_created_at ON combos (created_at DESC);

-- ============================================================================
-- COMBO <-> PRODUCT  (many-to-many with quantity)
-- ============================================================================
CREATE TABLE combo_products (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    combo_id    UUID NOT NULL REFERENCES combos(id) ON DELETE CASCADE,
    product_id  UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    quantity    INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
    UNIQUE (combo_id, product_id)   -- required: bulk endpoint uses ON CONFLICT (combo_id, product_id)
);

CREATE INDEX idx_combo_products_combo ON combo_products (combo_id);
CREATE INDEX idx_combo_products_product ON combo_products (product_id);

-- ============================================================================
-- COMBO <-> CATEGORY  (many-to-many, used for combo filtering)
-- ============================================================================
CREATE TABLE combo_categories (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    combo_id     UUID NOT NULL REFERENCES combos(id) ON DELETE CASCADE,
    category_id  UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE
);

CREATE INDEX idx_combo_categories_combo ON combo_categories (combo_id);
CREATE INDEX idx_combo_categories_category ON combo_categories (category_id);

-- ============================================================================
-- CUSTOM (BUILD-YOUR-OWN) COMBOS  (combos.ts POST /custom)
-- ============================================================================
CREATE TABLE custom_combos (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                  TEXT NOT NULL DEFAULT 'Custom Combo',
    description           TEXT,
    subtotal              NUMERIC(12,2),
    discount_percentage   NUMERIC(5,2),
    discount_amount       NUMERIC(12,2),
    total_price           NUMERIC(12,2),
    item_count            INTEGER,
    special_requests      TEXT,
    status                TEXT NOT NULL DEFAULT 'pending',
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE custom_combo_products (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    custom_combo_id   UUID NOT NULL REFERENCES custom_combos(id) ON DELETE CASCADE,
    product_id        UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    quantity          INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0)
);

CREATE INDEX idx_custom_combo_products_combo ON custom_combo_products (custom_combo_id);

-- ============================================================================
-- ORDERS  (orders.ts, payment.ts, admin.ts)
-- Line items are stored denormalized as JSONB in `items` — the backend never
-- writes normalized rows for an order's line items (see order_items below).
-- ============================================================================
CREATE TABLE orders (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    custom_order_id        TEXT UNIQUE,             -- e.g. "VEDIQRA#101" (prefix is configurable via ORDER_ID_PREFIX, see backend/src/config.ts)
    razorpay_order_id      TEXT,
    razorpay_payment_id    TEXT,
    razorpay_signature     TEXT,
    items                  JSONB NOT NULL DEFAULT '[]'::jsonb,
    subtotal               NUMERIC(12,2) DEFAULT 0,
    shipping_charge        NUMERIC(12,2) DEFAULT 0,
    cod_charge             NUMERIC(12,2),
    coupon_code            TEXT,
    coupon_discount        NUMERIC(12,2) DEFAULT 0,
    total_amount           NUMERIC(12,2) NOT NULL DEFAULT 0,
    grand_total            NUMERIC(12,2),
    customer_name          TEXT NOT NULL,
    customer_email         TEXT NOT NULL,
    customer_phone         TEXT NOT NULL,
    special_requests       TEXT,
    shipping_address       TEXT,
    shipping_city          TEXT,
    shipping_state         TEXT,
    shipping_pincode       TEXT,
    shipping_country       TEXT DEFAULT 'India',
    payment_method         TEXT NOT NULL DEFAULT 'cod',   -- 'cod' | 'online'
    status                 TEXT NOT NULL DEFAULT 'pending',
    tracking_number        TEXT,                          -- set by admin when shipping
    admin_notes            TEXT,
    paid_at                TIMESTAMPTZ,
    refund_data            JSONB,
    refunded_at            TIMESTAMPTZ,
    -- Phase 3B: stock ledger and refund tracking (see migrations/004_stock_restoration_and_refunds.sql)
    stock_movements        JSONB NOT NULL DEFAULT '[]'::jsonb,   -- stock actually decremented for this order
    stock_restored_at      TIMESTAMPTZ,                          -- set once when that stock was given back
    refunded_amount        NUMERIC(12,2) NOT NULL DEFAULT 0,     -- provider-confirmed refunds, rupees
    refunds                JSONB NOT NULL DEFAULT '[]'::jsonb,   -- [{id, request_id, amount, status, created_at}]
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT orders_refund_bounds CHECK (refunded_amount >= 0 AND refunded_amount <= total_amount)
);

CREATE INDEX idx_orders_created_at ON orders (created_at DESC);
CREATE INDEX idx_orders_status ON orders (status);
CREATE INDEX idx_orders_customer_phone ON orders (customer_phone);
CREATE INDEX idx_orders_customer_email ON orders (customer_email);
CREATE INDEX idx_orders_razorpay_order_id ON orders (razorpay_order_id);
-- One order per Razorpay payment: makes payment verification idempotent (retries cannot duplicate an order)
CREATE UNIQUE INDEX uq_orders_razorpay_payment_id ON orders (razorpay_payment_id) WHERE razorpay_payment_id IS NOT NULL;

-- Atomic order numbers (custom_order_id = <prefix>#<n>). Replaces "read the last order and add 1", which
-- produced duplicate numbers under concurrent checkouts.
CREATE SEQUENCE order_number_seq START WITH 100 MINVALUE 100;

-- ============================================================================
-- ORDER_ITEMS
-- NOTE: No route in this backend ever INSERTs into this table — order line
-- items live entirely inside orders.items (JSONB). The only reference is a
-- pre-delete safety check in admin.ts ("has this product ever been ordered?").
-- Table is created so that query does not fail against an empty database;
-- see the report for the recommendation to either wire this up or remove the
-- check. Shape below is inferred from the fields used in orders.items entries
-- (see backend/src/utils/emailTemplates.ts).
-- ============================================================================
CREATE TABLE order_items (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id              UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    product_id            UUID REFERENCES products(id) ON DELETE SET NULL,
    combo_id              UUID REFERENCES combos(id) ON DELETE SET NULL,
    name                  TEXT,
    quantity              INTEGER NOT NULL DEFAULT 1,
    price                 NUMERIC(12,2) NOT NULL DEFAULT 0,
    color_id              UUID REFERENCES product_colors(id) ON DELETE SET NULL,
    color_name            TEXT,
    size_id               UUID REFERENCES product_sizes(id) ON DELETE SET NULL,
    size_name             TEXT,
    size_code             TEXT,
    customization_data    JSONB,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_order_items_order ON order_items (order_id);
CREATE INDEX idx_order_items_product ON order_items (product_id);

-- ============================================================================
-- COUPONS  (coupons.ts)
