CREATE INDEX idx_coupon_usage_coupon ON coupon_usage (coupon_id);
CREATE INDEX idx_coupon_usage_email ON coupon_usage (coupon_id, customer_email);

-- ============================================================================
-- REVIEWS  (reviews.ts)
