CREATE TABLE popup_config (
    id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title                     TEXT NOT NULL,
    description               TEXT,
    image_url                 TEXT,
    discount_text             TEXT,
    discount_value            TEXT,
    timer_enabled             BOOLEAN NOT NULL DEFAULT TRUE,
    timer_hours               INTEGER NOT NULL DEFAULT 0,
    timer_minutes             INTEGER NOT NULL DEFAULT 59,
    timer_seconds             INTEGER NOT NULL DEFAULT 46,
    offer_text                TEXT,
    cta_text                  TEXT,
    cta_link                  TEXT,
    cash_on_delivery_text     TEXT,
    prepaid_discount_text     TEXT,
    is_active                 BOOLEAN NOT NULL DEFAULT TRUE,
    display_frequency         TEXT NOT NULL DEFAULT 'once_per_session', -- 'once_per_session' | 'always' | 'once_per_day'
    start_date                TIMESTAMPTZ,
    end_date                  TIMESTAMPTZ,
    created_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE popup_display_stats (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    popup_id     UUID NOT NULL REFERENCES popup_config(id) ON DELETE CASCADE,
    session_id   TEXT,
    viewed_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    clicked_at   TIMESTAMPTZ
);

CREATE INDEX idx_popup_display_stats_popup ON popup_display_stats (popup_id);

-- ============================================================================
-- SITE SETTINGS  (settings.ts) — simple generic key/value store
-- ============================================================================
CREATE TABLE site_settings (
    key          TEXT PRIMARY KEY,
    value        JSONB,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- ADMIN USERS  (routes/adminAuth.ts, middleware/auth.ts)
-- Passwords are stored ONLY as bcrypt hashes. Create the first admin with:
--   cd backend && npm run create-admin -- <username> <password>
-- ============================================================================
CREATE TABLE admin_users (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username       TEXT NOT NULL UNIQUE CHECK (username = lower(username)),
    password_hash  TEXT NOT NULL,
    role           TEXT NOT NULL DEFAULT 'admin',
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    last_login_at  TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON COLUMN products.track_stock IS 'TRUE: stock_quantity is enforced and decremented on order. FALSE: made to order, not tracked.';
COMMENT ON COLUMN product_option_values.stock_quantity IS 'NULL = not tracked (unlimited). A number is enforced and decremented on order.';
COMMENT ON COLUMN orders.stock_movements   IS 'Stock actually decremented for this order (products with track_stock, option values with tracked stock). Source of truth for restoration.';
COMMENT ON COLUMN orders.stock_restored_at IS 'Set once when stock_movements were given back (cancellation / full refund). Prevents double restoration.';
COMMENT ON COLUMN orders.refunded_amount   IS 'Total of provider-confirmed refunds, in rupees.';
COMMENT ON COLUMN orders.refunds           IS 'Provider-confirmed refunds: [{id, request_id, amount, status, created_at}].';
COMMENT ON TABLE product_colors IS 'DEPRECATED (Phase 2): migrated to product_option_values under group "colour". Not read by the API any more; drop after the old admin UI is retired.';
COMMENT ON TABLE product_sizes  IS 'DEPRECATED (Phase 2): migrated to product_option_values under group "size". Not read by the API any more; drop after the old admin UI is retired.';
COMMENT ON TABLE order_items    IS 'UNUSED: order lines are stored as an immutable JSONB snapshot in orders.items (product, base price, selected options with their prices, customization, quantity, line price).';


-- ============================================================================
-- End of schema
-- ============================================================================
